<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useUserCenterStore } from '../../stores/userCenter'; import type { Address } from '../../api/userCenter'
const store = useUserCenterStore(); const editing = ref<Address | null>(null); const form = ref({ name: '', phone: '', province: '', city: '', district: '', detail: '' }); const reset = () => { editing.value = null; form.value = { name: '', phone: '', province: '', city: '', district: '', detail: '' } }; function edit(a: Address) { editing.value = a; form.value = { name: a.name, phone: a.phone, province: a.province, city: a.city, district: a.district, detail: a.detail } } async function save() { if (!/^\d{11}$/.test(form.value.phone) || !form.value.name || !form.value.detail) { alert('请填写收货人、11位手机号和详细地址。'); return } await store.saveAddress(form.value, editing.value?.id); reset() } function confirmDelete(id: number) { if (confirm('确定删除这个地址吗？')) store.removeAddress(id) } onMounted(() => store.loadAddresses())
</script>
<template><div class="user-heading"><div><p class="eyebrow">地址管理</p><h1>收货地址</h1></div><button @click="reset">新增地址</button></div><div class="address-list"><article v-for="address in store.addresses" :key="address.id" class="address-card"><div><strong>{{ address.name }}</strong><span>{{ address.phone.slice(0, 3) }}****{{ address.phone.slice(-4) }}</span><em v-if="address.isDefault">默认地址</em><p>{{ address.province }}{{ address.city }}{{ address.district }}{{ address.detail }}</p></div><div class="address-actions"><button v-if="!address.isDefault" @click="store.makeDefault(address.id)">设为默认</button><button @click="edit(address)">编辑</button><button @click="confirmDelete(address.id)">删除</button></div></article></div><div v-if="editing || form.name || form.detail" class="user-panel address-form"><h2>{{ editing ? '编辑地址' : '新增地址' }}</h2><div class="form-grid"><input v-model="form.name" placeholder="收货人姓名"/><input v-model="form.phone" placeholder="手机号码" maxlength="11"/><input v-model="form.province" placeholder="省份"/><input v-model="form.city" placeholder="城市"/><input v-model="form.district" placeholder="区/县"/><input v-model="form.detail" placeholder="街道门牌号"/></div><button @click="save">保存地址</button><button class="secondary-button" @click="reset">取消</button></div></template>
